/* a colour along n stops, t of 1000 */
static uint16_t ne_ramp(const uint16_t *st, uint32_t n, int32_t t)
{
    int32_t s = (int32_t)n - 1, k;
    t = t < 0 ? 0 : t > 1000 ? 1000 : t;
    k = t * s / 1000;
    if (k >= s)
        k = s - 1;
    return ux_mix(st[k], st[k + 1], (t * s - k * 1000) / 10);
}

