/* 9 stored bytes -> *s (its nudge untouched): 0 for bytes no firmware wrote (FLAM with RATCH x2.., n above 4, ..) */
static int step_get9(step_t *s, const uint8_t *b)
{
    uint32_t meta = b[4], j;
    memcpy(s->note, b, 4);
    s->n = meta & 7u; s->time = (meta >> 3) & 3u; s->flags = (meta >> 5) & 3u;
    s->vel = b[5] & 127u; meta |= (b[5] & 128u) << 1u;   /* (RATCH bit 0 at bit 8 of meta) */
    s->hit = b[6]; s->acc = b[7];
    s->probability = b[8] & 127u; meta |= (b[8] & 128u) << 2u;   /* (bit 1 at bit 9) */
    if (((meta & 128u) && (meta >> 8)) || s->n > 4u || s->time > ST_REST || s->probability > 101u)
        return 0;                                       /* ((Skiff) FLAM: bit 7 of meta, with RATCH x1 only) */
    s->cond = 0;                                        /* (Skiff) the trig condition: bit 7 of the note bytes */
    for (j = 0; j < 4u; j++) {
        s->cond |= (uint8_t)((s->note[j] >> 7) << j);
        s->note[j] &= 127u;
    }
    if (s->cond >= TC_COUNT || (s->acc & ~(s->hit ? s->hit : (1u << s->n) - 1u)))   /* ((2.0) no hits: ties of its */
        return 0;                                                                   /* notes; 1.4 refuses them) */
    step_set_ratchet(s, (meta >> 8) + 1u);
    if (meta & 128u)
        s->flags |= SF_FLAM;
    return 1;
}

static uint32_t rp_get(uint32_t f)                     /* a field as the MENU steps it: 0..2 */
{
    uint32_t v = (ui_rec_prefs >> (2u * f)) & 3u;
    v = v == 3u ? 0u : v;
    return f == RP_LEVEL ? (v == 0u ? 1u : v == 1u ? 0u : 2u) : v;   /* (LEVEL: LOW MID HIGH, MID stored as 0) */
}

/* decimal with an optional fixed point: fmt_fix(buf, -63, 1) -> "-6.3" */
static void fmt_fix(char *b, int32_t v, int decimals)
{
    char t[12];
    int n = 0, neg = v < 0, i;
    uint32_t u = (uint32_t)(neg ? -v : v);
    do {
        t[n++] = (char)('0' + u % 10u);
        u /= 10u;
        if (n == decimals)
            t[n++] = '.';
    } while (u || n <= decimals);
    if (neg)
        t[n++] = '-';
    for (i = 0; i < n; i++)
        b[i] = t[n - 1 - i];
    b[n] = 0;
}

/* the page's mark: the entry track k is on, its pattern the track's (BK_NONE: none) */
static uint32_t bank_cur(uint32_t k)
{
    uint32_t e;
    k %= NTRK;
    e = lists.cur[k] % NENT;
    return lists.ent[k][e][0] && lists.ent[k][e][0] == trk_pid[k] ? e : BK_NONE;
}

/* .. EMPTY (its dialog's OCT+, stopped): pattern id's steps, NUDGEs and automation gone, its number, LEN DIV SWING GATE
 * DIR and every entry naming it kept; a track on it now empties too (its steps are what is kept of it). Said */
static void pool_empty(uint32_t id)
{
    char b[16];
    uint32_t k;
    id %= BK_POOL;
    if (!BK_ON || transport_busy() || pat_read(id, bk_rec)) {
        ui_message(!BK_ON ? "STORAGE ERROR" : transport_busy() ? "STOP TO EMPTY" : "NOTHING TO EMPTY");
        return;
    }
    rec_empty(bk_rec, 0);
    for (k = 0; k < NTRK; k++)
        if (trk_pid[k] == id + 1u) {
            track_defaults_steps(&trk[k]);
            trk_sig[k] = 0;
        }
    if (pool_flush_said(pat_keep_now(id, bk_rec) ? 4 : 0))
        return;
    str_cpy(b, "EMPTIED ", sizeof b);
    pat_num(b + 8, id);
    ui_message(b);
}

static int up_name_ok(const uint8_t *s, uint32_t n)   /* 1..12 printable ASCII */
{
    uint32_t i;
    if (!n || n > 12u)
        return 0;
    for (i = 0; i < n; i++)
        if (s[i] < 32u || s[i] > 126u)
            return 0;
    return 1;
}

/* the selected part's sound -> slot k (no pattern: the fields stay 0); name 0 or "": the automatic name
 * (up_auto_name); up_put's result. ((2.0, #20) Stored, the track's sound is the slot's: on it as a LOAD would put it,
 * its name on HOME, kept by a project and by RESTORE LAST, brought up to date at once) */
static int up_store(uint32_t k, const char *name)
{
    up_rec_t r;
    int16_t v[P_COUNT];
    uint32_t i;
    memset(&r, 0, sizeof r);
    r.used = UP_USED;
    r.engine = TSEL->eng_req;
    up_set_name(&r, k, name);
    for (i = 0; i < P_COUNT; i++)
        v[i] = (int16_t)motion_base_value(TSEL, i);
    up_set_sound(&r, v);                                /* ((2.0) version 6) */
    if (r.engine == ENGI_FM6 && TSEL->p[P_E7] == FM6_OWN && name && name[0]) {   /* (FM6 LAB) its own patch takes a
                                                         * typed name (its first 10: .syx keeps it); a factory patch
                                                         * (F n) and the automatic name leave it as it is */
        char a[16];
        up_auto_name(a, r.engine, k);
        if (!str_eq(a, name)) {
            uint32_t tr = trk_index(TSEL) % NTRK, n = str_len(name);
            uint8_t v[FP_SIZE + 1u];
            memcpy(v, fm6_patch[tr], sizeof v);
            for (i = 0; i < 10u; i++)
                v[FP_NAME + i] = (uint8_t)(i < n ? name[i] : ' ');
            fm6_set_patch(tr, v);
        }
    }
    {
        int rc = up_put(k, &r);                         /* the record first, then its FM6 patch (up_fm6.c) */
        if ((rc == 0 || rc == 3) && r.engine == ENGI_FM6) {
            int u = upf_store(k, (uint32_t)(TSEL - trk));
            if (u == 2)
                rc = 2;
        }
        if (rc == 0 || rc == 3) {
            for (i = 0; i < NTRK; i++)                  /* (another track on the slot plays what it had: off it) */
                if (trk[i].user == k + 1u)
                    trk[i].user = 0;
            TSEL->user = (uint8_t)(k + 1u);
            autosave_soon();
        }
        return rc;
    }
}

/* entry k out (the notes above down a place, their ties along); a step left with nothing: cleared; one left with notes
 * going on only: none of its own values (they were its starts') */
static void ed_del(step_t *s, uint32_t k)
{
    uint32_t x, m = s->acc, lo = (1u << k) - 1u, start = !step_tied(s, k);
    for (x = k; x + 1u < s->n; x++)
        s->note[x] = s->note[x + 1u];
    s->n--;
    if (!s->hit)
        s->acc = (uint8_t)((m & lo) | ((m >> 1) & ~lo));
    if (!s->n && !s->hit) {
        step_clear(s);
    } else if (start && !s->hit && step_ties(s) == (1u << s->n) - 1u) {
        s->flags = s->vel = s->probability = s->cond = 0;
        s->nudge = 0;
    }
}

/* a TIE that holds no note (its note cleared before 2.0: an empty step to the eye) */
static int tie_alone(const track_t *t, uint32_t i)
{
    return t->step[i].time == ST_TIE && pr_src(t, i, (uint32_t)t->p[P_SLEN]) == NSTEP;
}

/* the layer opened: once seen, no more hint; SET: what OCT- will put back */
static void layer_opened(uint32_t l)
{
    uint32_t k;
    if (!((layer_seen >> l) & 1u)) {
        layer_seen |= (uint8_t)(1u << l);
        settings_save();                                /* (deferred while playing) */
    }
    lys.l = (uint8_t)l;
    lys.trk = song.sel;
    lys.loaded = 0;
    lys.cook = 0;
    if (l == LAYER_SEQ || l == LAYER_REC) {             /* the track as it is now (OCT-): ((2.0) the undo copy of the */
        upin.pin = 0;                                   /* first change, ui.c upin) */
        upin.pin_next = 1;
    }
    for (k = 0; k < 4u; k++)
        if (l == LAYER_SEQ) {
            lys.v[k] = TSEL->p[P_SLEN + k];
        } else if (l != LAYER_GLO) {
            lys.v[k] = TSEL->p[P_ROOT + k];
            lys.v[4u + k] = k < 2u ? TSEL->p[P_CHRD + k] : 0;
        }
    for (k = 0; l == LAYER_GLO && k < NTRK; k++) {
        lys.v[k] = trk[k].p[P_MUTE];
        lys.v[NTRK + k] = trk[k].p[P_LEVEL];
    }
    lys.v[LY_BPM] = song.g[G_BPM];
    if (l == LAYER_REC)
        lys.v[0] = ui_rec_prefs;
    memcpy(lys.mute, drum_mute, sizeof lys.mute);
}

/* lane l at random, the drum machine way: the kick 3..5 a bar (one on step 1), the snare on beats 2 and 4, the
 * closed hat 8..12, the others sparse (any: they may stay empty, RANDOM; else at least one hit, RANDOM LANE) */
static void tl_lane_rnd(track_t *t, uint32_t len, uint32_t l, int any)
{
    tl_lane_clear(t, len, l);
    if (l == DV_KICK)
        tl_euclid(t, len, l, tl_per(3u + tl_rnd(3), len), 0, tl_rnd(2));
    else if (l == DV_SNARE)
        tl_euclid(t, len, l, tl_per(2, len), 4u % len, 0);
    else if (l == DV_HATC)
        tl_euclid(t, len, l, tl_per(8u + tl_rnd(5), len), tl_rnd(2), 0);
    else if (!any || !tl_rnd(l == DV_HATO ? 2u : 3u))
        tl_euclid(t, len, l, tl_per(1u + tl_rnd(2), len), l == DV_HATO ? (2u + 4u * tl_rnd(4)) % len : tl_rnd(len), 0);
    if (l == DV_SNARE && !tl_rnd(3))
        grid_hit(t, tl_rnd(len), l, 1);                 /* (a ghost snare now and then) */
}

static int32_t accel(uint32_t role, int32_t s, int32_t range)
{
    uint32_t now = fm1_ms & 0xFFFFFFu, st = ui.enc_t[role], up = s > 0, pi = st >> 25, a, i, m = 1;
    if (!(ui_prefs & PREF_ACCEL) || range <= 32 || !s)
        return s;
    a = (uint32_t)(s < 0 ? -s : s);
    i = ((now - st) & 0xFFFFFFu) / a;                   /* ms per detent of this read */
    if (!st || ((st >> 24) & 1u) != up || i >= ACC_GAP)
        i = 127u;                                       /* a new turn, or reversed */
    else if (pi < ACC_GAP) {
        m = ACC_RATE / (i > pi ? i : pi ? pi : 1u);
        a = range > 64 ? 8u : 4u;                       /* (the cap) */
        m = m < 1u ? 1u : m > a ? a : m;
    }
    ui.enc_t[role] = now | up << 24 | (i ? i : 1u) << 25;
    return s * (int32_t)m;
}

