/* the drives' and CRUSH's shape of v (a voice's full scale 32768; v already through the drive): the curve the INSERT
 * and DRIVE graphs draw too (ui_pgraph.c graph_insert, graph_drive) */
static inline int32_t ins_shape(uint32_t ty, int32_t v, uint32_t sh)
{
    switch (ty) {
    case IT_SOFT:
        return softclip(v);
    case IT_HARD:
        return clamp(v, -24000, 24000);
    case IT_FOLD: {
        int32_t u = (int32_t)((uint32_t)(v + 16384) & 0xFFFFu) - 32768;   /* a triangle of period 65536: +-16384 */
        u = 16384 - (u < 0 ? -u : u);
        return u + (u >> 1);                            /* x 1.5 (no divide) */
    }
    case IT_FUZZ:
        return v > 0 ? (v > 20000 ? 20000 : v) : softclip(v) >> 1;
    case IT_CRUSH:                                      /* sh: the bits taken (16 - BITS); to the nearest step */
        return ((v + ((1 << sh) >> 1)) >> sh) << sh;
    default:
        return v;
    }
}

/* half the pixels of a box in c (a checkerboard: the ASCII shade, blood in a saw's teeth) */
static void cr_dither(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t c)
{
    int32_t i, j;
    for (j = y; j < y + h; j++)
        for (i = x; i < x + w; i++)
            if (((i + j) & 1) == 0)
                cv_pset(i, j, c);
}

/* ANALOG's OSC: the wave three times as the oscillator makes it (SAW SQR TRI SIN PWM), the second one (MIX in) under
 * it, a little out (DETUNE), NOISE's specks */
static int32_t osc_shape(uint32_t w, uint32_t ph)    /* +-1000 */
{
    int32_t f = (int32_t)(ph >> 22);                 /* 0..1023 */
    switch (w) {
    case 1: return f < 512 ? 1000 : -1000;
    case 2: return f < 512 ? -1000 + f * 4000 / 1024 : 3000 - f * 4000 / 1024;
    case 3: return sine_i(ph) * 1000 / 32768;
    case 4: return f < 256 ? 1000 : -1000;
    default: return -1000 + f * 2000 / 1024;
    }
}

