static void fm1_main(void)
{
    uint32_t ms;
#if FELUCCA_CPU2
    uint8_t c1_told = 0;                                /* (Skiff 1.3) CORE 2 FAILED said (and the setting cleared) */
#endif
    persist_boot();
    bank_boot();                                        /* (Skiff) the pattern bank (bank.c) */
#if FELUCCA_OTA
    if (flash_ok)
        ota_boot_cleanup();                             /* staging area left by an update */
#endif
    if (settings_init())                                /* a new unit: the SKIFF palette, and BPM LOCK on (DESIGN.md */
        ui_prefs |= PREF_BPM_LOCK;                      /* rule 3: the tempo with GLO held, #58) */
    usb_serial_apply();                                 /* (#67: the saved USB SERIAL before usb_start) */
    lcd_init();
    draw_splash();                                      /* ui_draw.c (1.1.5) */
    if (felucca_dbg.magic != DBG_MAGIC) {
        memset(&felucca_dbg, 0, sizeof felucca_dbg);
        felucca_dbg.magic = DBG_MAGIC;
    }
    felucca_dbg.boots++;
    felucca_dbg.max_us = 0;
    felucca_dbg.in_audio = 0;                       /* .noinit: a reset inside the audio ISR left it set, and
                                                       TIMER5 would treat every tick as nested (no USB poll) */
    felucca_dbg.prev_stage = felucca_dbg.stage;     /* a WDT reset leaves the last breadcrumb here */
    felucca_dbg.prev_page = felucca_dbg.page;
    felucca_dbg.prev_home = felucca_dbg.home;
    felucca_dbg.prev_frames = felucca_dbg.ui_frames;
    felucca_dbg.prev_rst = fm1_boot.p3_rst;
    if (CLK320_SET && !bootguard.failed && clk320.state != CLK_TRIPPED) {
        /* (Skiff) MENU > CPU CLOCK 320 MHZ: from the boot stage's 360 to JieLi's rated 320 (hal/fm1_clk.h, curist's
         * switch), the screen up, on one core, before the scan, the second core, the audio and USB. Not after a failed
         * boot, nor again before a power-off after a reset during it (fm1_cstart: TRIPPED); a soft reset that kept 320
         * is not switched again (the check: EALREADY). Any other register not as expected: refused, said (below) */
        uint32_t t[2];
        lcd_sync();                                     /* (no LCD DMA through it) */
        clk320.state = CLK_ARMED;
        fm1_wdt_feed();
        clk320.why = (uint8_t)fm1_clk320_go(t);
        fm1_wdt_feed();
        clk320.state = !clk320.why ? CLK_ON : clk320.why == FM1_CLK320_EALREADY ? CLK_KEPT : CLK_REFUSED;
        if (t[1])                                       /* (the loop timed before and after: the clock it runs at) */
            clk320.loop_mhz = (uint16_t)((360u * t[0] + t[1] / 2u) / t[1]);
    }
    fm1_input_init();
    fm1_adc_init();
#if BOARD_SMK37 && FELUCCA_FLASH
    if (flash_ok)                                   /* the unit's key / pad velocity curves (USRTRIM, read only) */
        smk_trim_load(fm1_xip_ptr(SMK_TRIM_FLASH));
#endif
    panel_init();
    felucca_init();
#if BOARD_SMK37
    smk_ui_boot();                            /* (MASTER where it was left, KEY VELOCITY: smk_ui.c) */
#endif
    master_boot();
    kb_boot_hold = 1;                         /* #137: no notes from the keys before the UI (seq.c keyboard_block) */
#if FELUCCA_CPU2
    if (!bootguard.failed && CPU2_SET) {
        /* (Skiff 1.3, as Felucca 1.6.1) the second core (hal/fm1_cpu1.h; fx.c mix_block hands it tracks), at power-on,
         * before the audio and the timers (started later it never reaches its entry) and before fm1_guard_lock_top
         * (its entry word is at the top of RAM). It starts in the chip's ROM: the PC limits open meanwhile. MENU > CPU
         * 1 CORE (the default), a crash in the last boot's first 30 s, or no answer: never started, one core */
        fm1_guard_pc_open();
        fm1_cpu1_start();
        fm1_guard_enable(FM1_GUARD_PC);
    }
#endif
    audio_init();
    usb_start();
#if FELUCCA_UART
    uart_midi_init();
#endif
#if BOARD_SMK37
    smk_uart_tx_init();                       /* the TRS jack: MIDI OUT */
#endif
    boot_leds();
    timer5_start();
    fm1_guard_lock_top();
    fm1_irq_enable_all();
    fm1_delay_ms(30);
#ifndef FM1_OCT_BOTH
#define FM1_OCT_BOTH 3u                       /* (host builds: the FM-1's OCT- and OCT+, ids 0 and 1) */
#endif
    if ((fm1_in.buttons & FM1_OCT_BOTH) == FM1_OCT_BOTH) {
        panel_setup();                        /* OCT- + OCT+ held at power-on */
        settings_save();
    }
    if (ui_set_rev < 1u) {                    /* (Skiff U1) SELECT turns pages on every unit: a unit from Felucca */
        ui_prefs |= PREF_BPM_LOCK;            /* had BPM LOCK OFF (SELECT the tempo). Once: the MENU can turn it */
        ui_set_rev = 1;                       /* off again */
        settings_save();
    }
#if FELUCCA_LEGACY
    proj_migrate(boot_clean);                 /* (Skiff phase 5) projects of before: SKF2, their tracks patterns */
#endif
    unit_g_adopt = ui_set_rev < 2u;           /* (Skiff U3, R8) the first boot: the session's CLOCK MIDI IN TUNE .. */
    autosave_boot(boot_clean);                /* (1.2) the last session's music, under the splash */
    unit_g_boot();                            /* .. become the unit's; later the unit's are put back over it (ui.c) */
    for (ms = 0; ms < 400u; ms += 10u) {      /* the splash; the pot followed (MIDI IN plays under it) */
        fm1_delay_ms(10);
        master_poll();
    }
    kb_boot_hold = 0;
    lcd_fill(0, 0, 240, 240, T_BG);
    scrn.idle = fm1_ms;                        /* (MENU > SCREEN OFF: from here) */
    if (clk320.state == CLK_REFUSED)           /* (Skiff) MENU > CPU CLOCK 320 MHZ not switched, then why */
        ui_way("NO 320 MHZ", CLK_WHY[clk320.why % NELEM(CLK_WHY)]);
    else if (clk320.state == CLK_TRIPPED && CLK320_SET)
        ui_way("NO 320 MHZ", "RESET IN SWITCH");

    for (;;) {
        uint32_t m = fm1_ms;
        fm1_wdt_feed();
        usb_retry(fm1_ms);
        if (fm1_ms > 30000u && bootguard.pending) {     /* a crash or hang in the first 30 s counts */
            bootguard.pending = 0;
            bootguard.failed = 0;
        }
#if FELUCCA_CPU2
        if (*(volatile uint8_t *)&fm1_c1_gave_up && !c1_told) {   /* ((Skiff 1.3) the ISR's: core 1 misread or
                                                         * stopped answering on this FM-1: one core from now on, the
                                                         * setting back to 1 CORE (MENU > CPU 2 CORES tries again at the
                                                         * next power-on); said once */
            c1_told = 1;
            if (CPU2_SET) {
                CPU2_BYTE &= (uint8_t)~1u;
                settings_save();
            }
            ui_message("CORE 2 FAILED: 1 CORE");
        }
#endif
        {
            int32_t b = fm1_adc_read(FM1_ADC_BATT);     /* battery: slow IIR */
            if (b > 0)
                song.batt_raw = song.batt_raw ? song.batt_raw + (b - song.batt_raw) / 32 : b;
        }
        master_poll();
        {   /* OCT- + OCT+ held 5 s: enter UBOOT with RAM intact (debug / update); a countdown
             * shows from 2 s over the whole screen (the menu and the dialogs too: ui_draw), letting
             * go cancels it */
            static uint32_t t0;
            uint32_t both = (1u << panel.btn[B_OCTDN]) | (1u << panel.btn[B_OCTUP]);
            if ((fm1_in.buttons & both) != both) {
                if (ui.uboot) {
                    ui.uboot = 0;
                    ui.force = 1;                       /* what the countdown covered */
                    ui_message("UPDATE CANCELLED");
                }
                t0 = fm1_ms;
            } else if (fm1_ms - t0 > 2000u && fm1_ms - t0 <= 5000u) {
                uint32_t left = (5000u - (fm1_ms - t0) + 999u) / 1000u;
                if (left != ui.uboot) {
                    ui.uboot = (uint8_t)left;
                    ui.force = 1;
                }
            } else if (fm1_ms - t0 > 5000u) {
                fm1_audio_stop();
                scr_wake_now();
                lcd_fill(0, 0, 240, 240, T_BG);
                draw_text_box(0, 110, 240, &AF_M, "UPDATE MODE", T_THEME, 1);
                usb_detach();
                fm1_delay_ms(30);
                bootguard.pending = 0;                  /* intentional reset: not a failed boot */
                fm1_enter_uboot();
            }
        }
#if FELUCCA_OTA
        ed_service();                                   /* web editor SysEx */
#if SKIFF_BIG_SCREEN
        mirror_service();                               /* the FM-1 Big Screen mirror (skiff_mirror.c) */
#endif
        ota_service();                                  /* M-UPGRADE handshake */
        if (usb.ota_req) {                              /* M-UPGRADE upgrade command */
            usb.ota_req = 0;
            panic_req = (1u << NTRK) - 1u;               /* every track (bit per track) */
            scr_wake_now();                             /* (its progress on the screen) */
            if (flash_ok)
                ota_session();                          /* returns only if nothing was committed */
            lcd_fill(0, 0, 240, 240, T_BG);
            ui.force = 1;
        }
#endif
        if (usb.uboot_req) {                            /* SysEx F0 22 24 35 7D F7 from the host */
            fm1_audio_stop();
            scr_wake_now();
            lcd_fill(0, 0, 240, 240, T_BG);
            draw_text_box(0, 110, 240, &AF_M, "UPDATE MODE (USB)", T_THEME, 1);
            fm1_delay_ms(20);
            usb_detach();
            fm1_delay_ms(30);
            bootguard.pending = 0;
            fm1_enter_uboot();
        }
#if FELUCCA_CDC
        cdc_task();
#endif
        felucca_dbg.ui_frames++;
        felucca_dbg.page = ui.page;
        felucca_dbg.home = ui.home;
        felucca_dbg.stage = 1;
        ui_input();
#if BOARD_SMK37
        smk_ui_frame();                               /* the SMK-37's own controls (smk_ui.c) */
#endif
        settings_poll();                              /* queued settings save: only while stopped */
        autosave_poll();                              /* (1.2) the music, stopped and idle: project.c */
        felucca_dbg.stage = 2;
        ui_leds();
#if BOARD_SMK37
        padled_flush();                               /* the pads' colours, between LCD transfers (lcd.c) */
#endif
        ui_draw();
        felucca_dbg.stage = 9;
        while (fm1_ms - m < 15u) {                               /* ~60 UI frames/s at most */
            ui_input();
#if FELUCCA_OTA
            ed_service();                       /* editor replies without waiting for the next frame */
#endif
        }
    }
}

static void phase_note_on(track_t *t, voice_t *v)
{
    v->ph[1] = 0;
    v->ph[2] = 0;
    v->s[0] = 0;                 /* WAVE / WAVE2 toggle, line 1 */
    v->s[1] = 0;                 /* line 2 */
    v->s[4] = t->p[P_E7] > 0 ? 0 : PD_UNFOLDED;   /* FOLD's DC blocker (only FOLD > 0 reads them; kept on a */
    v->s[5] = 0;                                   /* retrigger: .keep) */
    v->s[6] = 163;               /* FOLD's last gain (phase_xfade): FOLD 1's, PD_FOLD_G0, until a folded block */
    v->s[7] = -1;                /* (#41) the last block's DCW (pd_bends): none yet (kept on a retrigger: .keep) */
}

static const param_desc_t *lofi_desc(const track_t *t, uint32_t k)
{
    if (k == 2u && t->p[P_E1] == RW_WRAM)
        return &LOFI_WAVNUM;
    if (k == 3u && t->p[P_E0] == CHIP_STEP)
        return &LOFI_DCY;
    return 0;
}

/* per part and block: the index follows SRC (and a new upload), grains of ended voices go,
 * one index entry is built */
static void grain_block(track_t *t)
{
    gr_part_t *P = (gr_part_t *)eng_part(t);   /* (Skiff: the part's shared area, engines.c) */
    uint32_t src = (uint32_t)t->p[P_E0] % SMP_NALL, st = gr_stamp(src), i;
    if (grain_off(t))
        return;
    if (!P->rng)
        P->rng = 0x2545F491;
    if (P->src != src + 1u || P->stamp != st) {
        gr_reset(P, src, st);
        for (i = 0; i < NVOICE; i++)
            if (t->v[i].active)
                t->v[i].s[0] = gr_find(src, t->v[i].note);
    }
    for (i = 0; i < GR_NG; i++)
        if (P->g[i].owner && !t->v[(P->g[i].owner - 1u) % NVOICE].active)
            P->g[i].owner = 0;
    gr_build(P, t);
}

/* n (<= 32) samples: out[i] = the resonator (Q20), aux[i] = the exciter (Q20). The exciter first (skipped
 * once a strike has rung out), then the modes */
static void px_modal_run(const px_modal_blk_t *B, px_modal_t *M, int32_t *out, int32_t *aux, uint32_t n)
{
    uint32_t i, k, nm = B->n;
    int32_t x[32];
    if (n > 32u)
        n = 32u;
    for (i = 0; i < n; i++)                              /* (no else below: a cold block after the function, */
        aux[i] = x[i] = 0;                               /* jumping back, reads as a loop to the budget) */
    if (B->dust_thr || B->strike || M->e1 || M->e2) {
        int32_t e1 = M->e1, e2 = M->e2, t, bp, big = 0;
        uint32_t rs = M->rng;
        const px_svf_t ex = B->ex;
        for (i = 0; i < n; i++) {                        /* ResonatorSvf<1>, low-pass */
            int64_t in = 0;
            if (B->dust_thr) {                           /* Dust */
                uint32_t u = px_rand(&rs);
                if (u < B->dust_thr)
                    in = (int64_t)(((((uint64_t)u * B->dust_inv) >> 32) * (uint32_t)B->dust_gain) >> 7);   /* Q24 */
            } else if (!i && B->strike) {
                in = (int64_t)B->strike << 8;
            }
            t = (int32_t)((ex.gh * (in - px_m(ex.rpg, e1, 28) - e2)) >> 30);
            bp = e1 + t;
            e1 = bp + t;
            t = px_m(ex.g, bp, 28);
            bp = e2 + t;                                 /* lp */
            e2 = bp + t;
            aux[i] = (bp >> 4) - (B->dust_thr ? B->dust_dc : 0);
            x[i] = bp >> 2;                              /* the modes run in Q22 */
            big |= (bp + 256) >> 9;                      /* |lp| >= 256 (Q24) somewhere in the block */
        }
        if (!big && !B->dust_thr && e1 > -256 && e1 < 256 && e2 > -256 && e2 < 256)
            e1 = e2 = 0;                                 /* rung out (-96 dB) */
        M->e1 = px_clamp(e1, -(1 << 30), 1 << 30);
        M->e2 = px_clamp(e2, -(1 << 30), 1 << 30);
        M->rng = rs;
    }
    for (i = 0; i < n; i++) {                            /* the modes, band-pass */
        int64_t acc = 0;
        const px_mode_t *c = B->m;
        int32_t (*st)[2] = M->s, xi = x[i];
        for (k = 0; k < nm; k++, c++, st++) {
            int32_t s1 = st[0][0], s2 = st[0][1], t, v;
            t = px_m(c->gh, xi - px_m(c->rpg, s1, 28) - s2, 30);
            v = s1 + t;
            st[0][0] = v + t;
            t = px_m(c->g, v, 28);
            st[0][1] = s2 + t + t;
            acc += (int64_t)c->a * v;
        }
        out[i] = (int32_t)(acc >> 30);                   /* Q28 * Q22 -> Q20 */
    }
}

/* --------------------------------------------------------------- voice --- */
static fm6_note_t *fm6_note_of(track_t *t, voice_t *v)
{
    uint32_t i;
    if (t < &trk[0] || t >= &trk[NPART])
        return 0;
    i = (uint32_t)(v - t->v);
    return i < FM6_POLY ? &((fm6_note_t *)eng_part(t))[i] : 0;   /* (Skiff: the part's shared area, engines.c) */
}

static void slice_note_on(track_t *t, voice_t *v)
{
    const int16_t *p = t->p;
    uint32_t src = slc_src_of(p), div = (uint32_t)clamp(p[P_E1], 0, SLC_DIV_MAN), rev = p[P_E5] != 0;
    uint32_t a, b, st, j;
    const slc_src_t *s = slc_get(src);
    v->ph[1] = 0;
    v->s[2] = v->s[3] = 0;
    v->s[5] = 32767;
    v->s[6] = 2;
    v->s[7] = 0;
    v->env_out = 0;                                     /* a new slice fades in over one block */
    if (!s) {                                           /* no material: the sine (from phase 0: no click) */
        v->s[4] = (int32_t)SLC_SINE;
        v->s[6] = 1;
        v->ph[0] = 0;
        return;
    }
    j = slc_note_slice(p, v->note, slc_count(s, div));
    slc_bounds(s, div, j, &a, &b, &st);
    if (b <= a || (rev && !slc_rb(t, v)))
        return;
    v->s[4] = (int32_t)(src | (st >> 24) << 3 | rev << 7 | j << 8 | div << 16);
    v->s[6] = 0;
    if (rev) {
        v->ph[0] = b;
        v->ph[2] = a;
        v->s[0] = 0x7FFFFFFF;                           /* no window yet */
    } else {
        v->ph[0] = a;
        v->ph[2] = b;
        v->s[0] = (int16_t)(st & 0xFFFFu);
        v->s[1] = (int32_t)((st >> 16) & 127u);
    }
}

/* the lowest key is slice 0 (C4 + ROOT), no scale */
static int32_t slice_keys(const track_t *t, uint32_t k)
{
    return clamp(SLC_BASE + t->p[P_ROOT] + 12 * song.octave + (int32_t)k, 0, 127);
}

/* a breakpoint's handle: a ring 9 px across on a dark halo; filled: the one the knob just turned. (FM6 LAB T) CRYPT a
 * skull (the one turned aflame, its eyes blood), NEON a sparkle (the one turned cyan and twice the size), QUARK a
 * nucleus (the one turned gold, larger) */
static void fm_ring(int32_t x, int32_t y, int filled)
{
    int32_t dx, dy;
    if (ux.crypt) {
        for (dx = 0; dx < 4; dx++)                      /* (in a dark outline: on the lines) */
            cr_skull(x - 4 + (dx == 0) - (dx == 1), y - 4 + (dx == 2) - (dx == 3), T_BG, T_BG, 0);
        cr_skull(x - 4, y - 4, filled ? CR_FLAME : T_TEXT, filled ? CR_BLOOD : T_BG, 0);
        return;
    }
    if (ux.neon) {
        ne_spark(x, y, filled ? T_ACCENT : T_THEME, filled ? 2 : 1);
        return;
    }
    if (ux.quark) {
        qk_disc(x, y, 3, T_SURF);
        qk_nucleus(x, y, filled ? T_ACCENT : T_THEME, filled ? 9 : 7);
        return;
    }
    for (dy = -5; dy <= 5; dy++)
        for (dx = -5; dx <= 5; dx++) {
            int32_t d2 = dx * dx + dy * dy;
            if (d2 <= 30)
                cv_pset(x + dx, y + dy, d2 > 20 ? T_BG : d2 >= 7 || filled ? T_TEXT : T_SURF);
        }
}

static void fm_range_labels(void)
{
    char b[12];
    b[0] = '+';
    if (fm_prng < 100)
        fm_hundredths(b + 1, fm_prng);
    else
        fmt_int(b + 1, fm_prng / 100);
    str_cpy(b + str_len(b), " ST", sizeof b - str_len(b));
    cv_text_on(10, FM_GY + CAP_IN(S, 12), &AF_S, b, T_MID, T_SURF);
    b[0] = '-';
    cv_text_on(10, FM_GY + FM_GH - 12 + CAP_IN(S, 12), &AF_S, b, T_MID, T_SURF);
}
